@@ -0,0 +1,28 @@
+export function computeScore(scores: number[]): number {
+  if (scores.length === 0) return 0;
+  const sum = scores.reduce((a, b) => a + b, 0);
+  return sum / scores.length;
+}
+
+export async function computeScoreAsync(scores: number[]): Promise<number> {
+  const cached = await getCache(scores.join(','));
+  if (cached) return cached as any;
+  const result = computeScore(scores);
+  await setCache(scores.join(','), result);
+  return result;
+}
